//! Simulates separate volatile ID / persistent ID, Boot and APP states. Protocol
//! packing is checked separately against vectors generated by the official SDK.
use super::*;
use crate::unitree_protocol::crc32;
use std::collections::VecDeque;

#[derive(Clone, Copy, PartialEq)]
enum Fault {
    None,
    RejectUnlock,
    WrongWriteEcho,
    CorruptWriteAck,
    MissingSaveAck,
    RejectSave,
    WrongSavedReadback,
    DropRestoreAck,
    NoAppRecovery,
    WrongSaveCommand,
    SerialFailure,
}

struct Model {
    id: u8,
    saved_id: u8,
    boot: bool,
    unlocked: bool,
    conflict: Option<u8>,
    fault: Fault,
    write_count: usize,
    save_count: usize,
    pending_save: bool,
    frames: Vec<Vec<u8>>,
}
struct Control {
    model: Mutex<Model>,
    hold_save_ack: AtomicBool,
}
struct BootSerial {
    control: Arc<Control>,
    input: VecDeque<u8>,
}

fn boot_reply(id: u8, code: u8, command: u8, address: u16, accepted: bool, data: &[u8]) -> Vec<u8> {
    let mut reply = vec![0; data.len() + 18];
    reply[..6].copy_from_slice(&[
        0xfc,
        0xee,
        id | if accepted { 0xf0 } else { 0x70 },
        (code << 4) | command,
        address as u8,
        (address >> 8) as u8,
    ]);
    reply[6..6 + data.len()].copy_from_slice(data);
    let end = reply.len() - 4;
    let checksum = crc32(&reply[2..end]);
    reply[end..].copy_from_slice(&checksum.to_le_bytes());
    reply
}

impl Read for BootSerial {
    fn read(&mut self, data: &mut [u8]) -> io::Result<usize> {
        let held = self.control.model.lock().unwrap().pending_save
            && self.control.hold_save_ack.load(Ordering::Acquire);
        if self.input.is_empty() || held {
            std::thread::sleep(Duration::from_millis(1));
            return Err(io::ErrorKind::TimedOut.into());
        }
        // Deliberately fragment both USB echo and replies across many reads.
        let count = data.len().min(5).min(self.input.len());
        for byte in &mut data[..count] {
            *byte = self.input.pop_front().unwrap();
        }
        Ok(count)
    }
}

impl Write for BootSerial {
    fn write(&mut self, frame: &[u8]) -> io::Result<usize> {
        let mut m = self.control.model.lock().unwrap();
        let id = frame[2] & 15;
        if m.fault == Fault::SerialFailure && id == 3 {
            return Err(io::ErrorKind::BrokenPipe.into());
        }
        m.frames.push(frame.to_vec());
        assert!(id < 15, "configuration must never broadcast");
        let end = frame.len() - 4;
        assert_eq!(
            crc32(&frame[..end]),
            u32::from_le_bytes(frame[end..].try_into().unwrap())
        );
        self.input.extend(frame); // TX echo is not an acknowledgment.
        if frame[2] & 0xf0 != 0xf0 {
            assert_eq!(frame.len(), 20);
            assert_ne!(frame[2] & 0x70, 0x10, "configuration must never enable FOC");
            if id == m.id && frame[2] & 0x70 == 0x70 {
                m.boot = true;
            } else if (id == m.id && !m.boot) || Some(id) == m.conflict {
                let mut feedback = [0; 26];
                feedback[..6].copy_from_slice(&[0xfc, 0xee, id, 25, 30, 24]);
                let checksum = crc32(&feedback[2..22]);
                feedback[22..].copy_from_slice(&checksum.to_le_bytes());
                self.input.extend(feedback);
            }
            return Ok(frame.len());
        }
        if id != m.id || !m.boot {
            return Ok(frame.len());
        }
        let code = frame[5] >> 4;
        let command = frame[5] & 15;
        let address = u16::from_le_bytes([frame[6], frame[7]]);
        let mut data = vec![0; if code == 8 { 16 } else { 8 }];
        let mut accepted = true;
        let mut reply_command = command;
        let mut drop_ack = false;
        match (command, address) {
            (0, 0x20) => data = (0xa0..0xb0).collect(),
            (1, 0x10) => {
                assert_eq!(frame[8..24], (0xa0..0xb0).collect::<Vec<_>>());
                accepted = m.fault != Fault::RejectUnlock;
                m.unlocked = accepted;
            }
            (1, 4) => {
                assert!(m.unlocked);
                m.write_count += 1;
                m.id = frame[8];
                data[0] = if m.fault == Fault::WrongWriteEcho {
                    m.id + 1
                } else {
                    m.id
                };
            }
            (2, 0) => {
                assert!(m.unlocked);
                m.save_count += 1;
                m.pending_save = true;
                accepted = m.fault != Fault::RejectSave;
                if accepted {
                    m.saved_id = m.id;
                }
                drop_ack = m.fault == Fault::MissingSaveAck;
                if m.fault == Fault::WrongSaveCommand {
                    reply_command = 1;
                }
            }
            (0, 4) => {
                data[0] = if m.fault == Fault::WrongSavedReadback {
                    m.id + 1
                } else {
                    m.id
                }
            }
            (5, 0) => {
                m.boot = m.fault == Fault::NoAppRecovery;
                m.unlocked = false;
                m.pending_save = false;
                drop_ack = m.fault == Fault::DropRestoreAck || m.fault == Fault::NoAppRecovery;
            }
            _ => panic!("unexpected Boot command {command} address {address}"),
        }
        if !drop_ack {
            let mut reply = boot_reply(id, code, reply_command, address, accepted, &data);
            if m.fault == Fault::CorruptWriteAck && command == 1 && address == 4 {
                reply[6] ^= 1;
            }
            self.input.extend(reply);
        }
        Ok(frame.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}
impl SerialIo for BootSerial {
    fn clear_input(&mut self) -> io::Result<()> {
        self.input.clear();
        Ok(())
    }
}

async fn simulated(fault: Fault, conflict: Option<u8>) -> (Arc<ServoSession>, Arc<Control>) {
    let control = Arc::new(Control {
        model: Mutex::new(Model {
            id: 0,
            saved_id: 0,
            boot: false,
            unlocked: false,
            conflict,
            fault,
            write_count: 0,
            save_count: 0,
            pending_save: false,
            frames: vec![],
        }),
        hold_save_ack: AtomicBool::new(false),
    });
    let app = ServoSession::start(
        "Boot simulation".into(),
        0,
        ServoSettings {
            response_timeout_ms: 5,
            ..ServoSettings::default()
        },
        Box::new(BootSerial {
            control: control.clone(),
            input: VecDeque::new(),
        }),
    )
    .unwrap();
    app.execute(ServoOperation::Select(0)).await.unwrap();
    (app, control)
}

#[tokio::test]
async fn id_is_saved_read_back_and_selected_without_motion() {
    let (app, control) = simulated(Fault::None, None).await;
    let state = app
        .execute(ServoOperation::ChangeId {
            old_id: 0,
            new_id: 3,
        })
        .await
        .unwrap();
    assert_eq!(state.selected_id, Some(3));
    assert!(
        state.online
            && state.stop_confirmed
            && !state.motion_active
            && state.bootloader_ids.is_empty()
    );
    let result = state.id_change.unwrap();
    assert_eq!(result.phase, IdChangePhase::Complete);
    assert!(result.saved && result.error.is_none());
    assert!(state.devices.iter().all(|d| d.id != 0));
    {
        let mut model = control.model.lock().unwrap();
        assert_eq!((model.write_count, model.save_count), (1, 1));
        assert_eq!(model.saved_id, 3);
        model.id = model.saved_id; // simulated loss of volatile state
        model.boot = false;
    }
    app.execute(ServoOperation::Select(3)).await.unwrap();
    assert!(app.execute(ServoOperation::Select(0)).await.is_err());
    app.execute(ServoOperation::Select(3)).await.unwrap();
    app.shutdown(false).await.unwrap();
}

#[tokio::test]
async fn invalid_stale_occupied_or_disconnected_id_never_reaches_boot() {
    for (fault, conflict) in [(Fault::None, Some(3)), (Fault::SerialFailure, None)] {
        let (app, control) = simulated(fault, conflict).await;
        for (old_id, new_id) in [(0, 0), (0, 15), (2, 3), (0, 3)] {
            assert!(app
                .execute(ServoOperation::ChangeId { old_id, new_id })
                .await
                .is_err());
        }
        assert!(control
            .model
            .lock()
            .unwrap()
            .frames
            .iter()
            .all(|p| p[2] & 0x70 == 0));
        app.shutdown(false).await.unwrap();
    }
}

#[tokio::test]
async fn rejected_unlock_never_writes_id_and_recovers_old_app() {
    let (app, control) = simulated(Fault::RejectUnlock, None).await;
    assert!(app
        .execute(ServoOperation::ChangeId {
            old_id: 0,
            new_id: 3
        })
        .await
        .is_err());
    let state = app.snapshot();
    assert_eq!(state.selected_id, Some(0));
    assert!(state.online && state.stop_confirmed);
    assert!(!state.id_change.unwrap().write_attempted);
    assert_eq!(control.model.lock().unwrap().write_count, 0);
    app.shutdown(false).await.unwrap();
}

#[tokio::test]
async fn corrupt_or_wrong_write_reply_never_saves_and_finds_new_address() {
    for fault in [Fault::WrongWriteEcho, Fault::CorruptWriteAck] {
        let (app, control) = simulated(fault, None).await;
        assert!(app
            .execute(ServoOperation::ChangeId {
                old_id: 0,
                new_id: 3
            })
            .await
            .is_err());
        let state = app.snapshot();
        assert_eq!(state.selected_id, Some(3));
        assert!(state.online && state.stop_confirmed);
        let result = state.id_change.unwrap();
        assert!(result.write_attempted && !result.saved);
        assert!(result.error.unwrap().contains("UNCONFIRMED"));
        assert_eq!(control.model.lock().unwrap().save_count, 0);
        if fault == Fault::CorruptWriteAck {
            assert!(state.crc_error_count > 0);
        }
        app.shutdown(false).await.unwrap();
    }
}

#[tokio::test]
async fn save_requires_matching_positive_crc_valid_ack_and_is_not_retried() {
    for fault in [
        Fault::MissingSaveAck,
        Fault::RejectSave,
        Fault::WrongSaveCommand,
    ] {
        let (app, control) = simulated(fault, None).await;
        assert!(app
            .execute(ServoOperation::ChangeId {
                old_id: 0,
                new_id: 3
            })
            .await
            .is_err());
        let state = app.snapshot();
        assert_eq!(state.selected_id, Some(3));
        assert!(state.online && state.stop_confirmed);
        assert!(!state.id_change.unwrap().saved);
        assert_eq!(control.model.lock().unwrap().save_count, 1);
        app.shutdown(false).await.unwrap();
    }
}

#[tokio::test]
async fn readback_mismatch_retains_acknowledged_save_but_never_claims_completion() {
    let (app, _) = simulated(Fault::WrongSavedReadback, None).await;
    assert!(app
        .execute(ServoOperation::ChangeId {
            old_id: 0,
            new_id: 3
        })
        .await
        .is_err());
    let change = app.snapshot().id_change.unwrap();
    assert_eq!(change.phase, IdChangePhase::Failed);
    assert!(change.saved);
    assert!(change.error.unwrap().contains("readback mismatch"));
    app.shutdown(false).await.unwrap();
}

#[tokio::test]
async fn fresh_app_feedback_can_confirm_recovery_when_boot_jump_ack_is_lost() {
    let (app, _) = simulated(Fault::DropRestoreAck, None).await;
    let result = app
        .execute(ServoOperation::ChangeId {
            old_id: 0,
            new_id: 3,
        })
        .await
        .unwrap();
    assert!(result.online && result.stop_confirmed);
    assert_eq!(result.id_change.unwrap().phase, IdChangePhase::Complete);
    app.shutdown(false).await.unwrap();
}

#[tokio::test]
async fn failed_app_recovery_blocks_motion_until_explicit_recovery_succeeds() {
    let (app, control) = simulated(Fault::NoAppRecovery, None).await;
    assert!(app
        .execute(ServoOperation::ChangeId {
            old_id: 0,
            new_id: 3
        })
        .await
        .is_err());
    let state = app.snapshot();
    assert!(!state.online && !state.stop_confirmed && !state.bootloader_ids.is_empty());
    assert!(state.id_change.unwrap().saved);
    assert!(app
        .execute(ServoOperation::Send {
            target: ServoTarget::default(),
            repeat: true
        })
        .await
        .is_err());
    assert!(app.shutdown(false).await.is_err());
    assert!(app.snapshot().connected);
    control.model.lock().unwrap().fault = Fault::None;
    let recovered = app.execute(ServoOperation::RestoreApp(3)).await.unwrap();
    assert_eq!(recovered.selected_id, Some(3));
    assert!(recovered.online && recovered.stop_confirmed && recovered.bootloader_ids.is_empty());
    assert!(recovered.devices.iter().all(|d| d.id != 0));
    assert_eq!(control.model.lock().unwrap().save_count, 1);
    app.shutdown(false).await.unwrap();
}

#[tokio::test]
async fn stop_during_flash_save_waits_for_save_and_app_recovery() {
    let (app, control) = simulated(Fault::None, None).await;
    control.hold_save_ack.store(true, Ordering::Release);
    let writer = app.clone();
    let writing = tokio::spawn(async move {
        writer
            .execute(ServoOperation::ChangeId {
                old_id: 0,
                new_id: 3,
            })
            .await
    });
    let deadline = Instant::now() + Duration::from_secs(1);
    while !control.model.lock().unwrap().pending_save {
        assert!(Instant::now() < deadline);
        tokio::time::sleep(Duration::from_millis(5)).await;
    }
    let stopper = app.clone();
    let stopping = tokio::spawn(async move { stopper.execute(ServoOperation::Stop).await });
    tokio::time::sleep(Duration::from_millis(30)).await;
    assert!(!stopping.is_finished());
    // Enqueue after Stop has incremented its epoch: configuration completion
    // itself must invalidate this target for the previous servo selection.
    let queued_sender = app.clone();
    let queued_target = tokio::spawn(async move {
        queued_sender
            .execute(ServoOperation::Send {
                target: ServoTarget::default(),
                repeat: true,
            })
            .await
    });
    tokio::time::sleep(Duration::from_millis(10)).await;
    control.hold_save_ack.store(false, Ordering::Release);
    assert_eq!(
        writing.await.unwrap().unwrap().id_change.unwrap().phase,
        IdChangePhase::Complete
    );
    assert!(stopping.await.unwrap().unwrap().stop_confirmed);
    assert!(queued_target.await.unwrap().is_err());
    assert!(!app.snapshot().motion_active);
    assert_eq!(control.model.lock().unwrap().save_count, 1);
    app.shutdown(false).await.unwrap();
}
